-- Additive memory schema over the principal storage tables. Existing columns keep their meaning.
ALTER TABLE memories ADD COLUMN trust TEXT NOT NULL DEFAULT 'agent' CHECK(trust IN ('user','agent','untrusted_external'));
ALTER TABLE memories ADD COLUMN attribute TEXT;
ALTER TABLE memories ADD COLUMN invalidated_at INTEGER;
ALTER TABLE memories ADD COLUMN last_used_at INTEGER;
ALTER TABLE memories ADD COLUMN origin_conversation TEXT;
ALTER TABLE memories ADD COLUMN origin_task TEXT;
ALTER TABLE memories ADD COLUMN normalized TEXT NOT NULL DEFAULT '';
ALTER TABLE memories ADD COLUMN similarity_pending INTEGER NOT NULL DEFAULT 0;
CREATE INDEX memories_principal_scope_state ON memories(principal_id,scope_id,state);
CREATE INDEX memories_scope_attribute ON memories(scope_id,attribute);
CREATE TABLE memory_entity_links(memory_id TEXT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,entity_id TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,PRIMARY KEY(memory_id,entity_id));
CREATE INDEX memory_entity_links_entity ON memory_entity_links(entity_id);
CREATE TABLE memory_transitions(id INTEGER PRIMARY KEY,memory_id TEXT NOT NULL,from_state TEXT,to_state TEXT NOT NULL,reason TEXT NOT NULL,at INTEGER NOT NULL);
CREATE TABLE memory_admissions(id TEXT PRIMARY KEY NOT NULL,principal_id TEXT NOT NULL,scope_id TEXT NOT NULL,memory_id TEXT NOT NULL,decision TEXT NOT NULL,similarity REAL,against_id TEXT,classifier TEXT NOT NULL,detail TEXT NOT NULL CHECK(json_valid(detail)),at INTEGER NOT NULL);
CREATE TABLE memory_questions(id TEXT PRIMARY KEY NOT NULL,principal_id TEXT NOT NULL,scope_id TEXT NOT NULL,memory_ids TEXT NOT NULL CHECK(json_valid(memory_ids)),question TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'low',state TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL);
CREATE TABLE memory_keys(id TEXT PRIMARY KEY NOT NULL,principal_id TEXT NOT NULL,scope_id TEXT NOT NULL,message_id TEXT NOT NULL,memory_id TEXT,key_text TEXT NOT NULL);
CREATE INDEX memory_keys_message ON memory_keys(message_id);
CREATE VIRTUAL TABLE memory_keys_fts USING fts5(key_text,content='memory_keys',content_rowid='rowid',tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER memory_keys_fts_insert AFTER INSERT ON memory_keys BEGIN INSERT INTO memory_keys_fts(rowid,key_text) VALUES(NEW.rowid,NEW.key_text); END;
CREATE TRIGGER memory_keys_fts_delete AFTER DELETE ON memory_keys BEGIN INSERT INTO memory_keys_fts(memory_keys_fts,rowid,key_text) VALUES('delete',OLD.rowid,OLD.key_text); END;
CREATE VIRTUAL TABLE memories_trigram USING fts5(statement,content='memories',content_rowid='rowid',tokenize='trigram');
CREATE TRIGGER memories_trigram_insert AFTER INSERT ON memories BEGIN INSERT INTO memories_trigram(rowid,statement) VALUES(NEW.rowid,NEW.statement); END;
CREATE TRIGGER memories_trigram_delete AFTER DELETE ON memories BEGIN INSERT INTO memories_trigram(memories_trigram,rowid,statement) VALUES('delete',OLD.rowid,OLD.statement); END;
CREATE TRIGGER memories_trigram_update AFTER UPDATE OF statement ON memories BEGIN INSERT INTO memories_trigram(memories_trigram,rowid,statement) VALUES('delete',OLD.rowid,OLD.statement); INSERT INTO memories_trigram(rowid,statement) VALUES(NEW.rowid,NEW.statement); END;
INSERT INTO memories_trigram(memories_trigram) VALUES('rebuild');
CREATE VIRTUAL TABLE messages_trigram USING fts5(text,content='messages',content_rowid='rowid',tokenize='trigram');
CREATE TRIGGER messages_trigram_insert AFTER INSERT ON messages BEGIN INSERT INTO messages_trigram(rowid,text) VALUES(NEW.rowid,NEW.text); END;
CREATE TRIGGER messages_trigram_delete AFTER DELETE ON messages BEGIN INSERT INTO messages_trigram(messages_trigram,rowid,text) VALUES('delete',OLD.rowid,OLD.text); END;
CREATE TRIGGER messages_trigram_update AFTER UPDATE OF text ON messages BEGIN INSERT INTO messages_trigram(messages_trigram,rowid,text) VALUES('delete',OLD.rowid,OLD.text); INSERT INTO messages_trigram(rowid,text) VALUES(NEW.rowid,NEW.text); END;
INSERT INTO messages_trigram(messages_trigram) VALUES('rebuild');
CREATE VIRTUAL TABLE doc_chunks_trigram USING fts5(text,content='doc_chunks',content_rowid='rowid',tokenize='trigram');
CREATE TRIGGER doc_chunks_trigram_insert AFTER INSERT ON doc_chunks BEGIN INSERT INTO doc_chunks_trigram(rowid,text) VALUES(NEW.rowid,NEW.text); END;
CREATE TRIGGER doc_chunks_trigram_delete AFTER DELETE ON doc_chunks BEGIN INSERT INTO doc_chunks_trigram(doc_chunks_trigram,rowid,text) VALUES('delete',OLD.rowid,OLD.text); END;
CREATE TRIGGER doc_chunks_trigram_update AFTER UPDATE OF text ON doc_chunks BEGIN INSERT INTO doc_chunks_trigram(doc_chunks_trigram,rowid,text) VALUES('delete',OLD.rowid,OLD.text); INSERT INTO doc_chunks_trigram(rowid,text) VALUES(NEW.rowid,NEW.text); END;
INSERT INTO doc_chunks_trigram(doc_chunks_trigram) VALUES('rebuild');
ALTER TABLE embedding_spaces ADD COLUMN provider TEXT NOT NULL DEFAULT 'local';
ALTER TABLE embedding_spaces ADD COLUMN source_dimensions INTEGER;
ALTER TABLE embedding_spaces ADD COLUMN migrated_from TEXT;
ALTER TABLE embedding_spaces ADD COLUMN activated_at INTEGER;
CREATE TABLE memory_index_queue(space_id TEXT NOT NULL,principal_id TEXT NOT NULL,scope_id TEXT NOT NULL,object_id TEXT NOT NULL,text TEXT NOT NULL,enqueued_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,PRIMARY KEY(space_id,scope_id,object_id));
CREATE TABLE memory_vector_objects(space_id TEXT NOT NULL,scope_id TEXT NOT NULL,object_id TEXT NOT NULL,principal_id TEXT NOT NULL,text_hash TEXT NOT NULL,vector BLOB NOT NULL,indexed_at INTEGER NOT NULL,PRIMARY KEY(space_id,scope_id,object_id));
CREATE TABLE relation_needs(id INTEGER PRIMARY KEY,principal_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT,memory_id TEXT,observed_at INTEGER NOT NULL);
ALTER TABLE relation_types ADD COLUMN merged_into TEXT;
ALTER TABLE relation_types ADD COLUMN proposed_at INTEGER;
CREATE UNIQUE INDEX relation_types_principal_name ON relation_types(principal_id,name);
CREATE INDEX entities_scope ON entities(principal_id,scope_id);
CREATE INDEX edges_memory_scope ON edges(layer,scope_id,source_id);
ALTER TABLE identity_docs ADD COLUMN kind TEXT NOT NULL DEFAULT 'notebook';
ALTER TABLE identity_docs ADD COLUMN icon TEXT;
ALTER TABLE identity_docs ADD COLUMN base_document_id TEXT;
ALTER TABLE doc_fragments ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0;
CREATE TABLE doc_fragment_versions(fragment_id TEXT NOT NULL,version INTEGER NOT NULL,document_id TEXT NOT NULL,heading_path TEXT NOT NULL,ordinal INTEGER NOT NULL,text TEXT NOT NULL,hash TEXT NOT NULL,deleted INTEGER NOT NULL,operation TEXT NOT NULL,actor TEXT,provenance TEXT NOT NULL CHECK(json_valid(provenance)),recorded_at INTEGER NOT NULL,PRIMARY KEY(fragment_id,version));
CREATE TABLE doc_edit_mismatches(actor TEXT NOT NULL,fragment_id TEXT NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(actor,fragment_id));
CREATE TABLE profile_proposals(id TEXT PRIMARY KEY NOT NULL,principal_id TEXT NOT NULL,document_id TEXT NOT NULL,fragment_id TEXT,heading_path TEXT NOT NULL,operation TEXT NOT NULL,text TEXT NOT NULL,normalized TEXT NOT NULL,provenance TEXT NOT NULL CHECK(json_valid(provenance)),evidence_count INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL DEFAULT 'proposed',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE notebook_timeline(id INTEGER PRIMARY KEY,document_id TEXT NOT NULL,scope_id TEXT NOT NULL,fragment_id TEXT NOT NULL,text TEXT NOT NULL,recorded_at INTEGER NOT NULL);
ALTER TABLE documents ADD COLUMN title TEXT NOT NULL DEFAULT '';
ALTER TABLE documents ADD COLUMN content_hash TEXT;
ALTER TABLE documents ADD COLUMN paginated INTEGER NOT NULL DEFAULT 0;
ALTER TABLE documents ADD COLUMN library INTEGER NOT NULL DEFAULT 0;
CREATE TABLE document_versions(document_id TEXT NOT NULL REFERENCES documents(id),version INTEGER NOT NULL,blob_hash TEXT NOT NULL REFERENCES blobs(hash),content_hash TEXT NOT NULL,kind TEXT NOT NULL,origin TEXT,title TEXT NOT NULL,paginated INTEGER NOT NULL,recorded_at INTEGER NOT NULL,PRIMARY KEY(document_id,version));
CREATE TRIGGER document_versions_blob_ref AFTER INSERT ON document_versions BEGIN INSERT OR REPLACE INTO blob_refs(owner_type,owner_id,slot,hash) VALUES('document_versions',NEW.document_id||'@'||NEW.version,'original',NEW.blob_hash); END;
CREATE TRIGGER document_versions_blob_unref AFTER DELETE ON document_versions BEGIN DELETE FROM blob_refs WHERE owner_type='document_versions' AND owner_id=OLD.document_id||'@'||OLD.version; END;
ALTER TABLE doc_chunks ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE doc_chunks ADD COLUMN ordinal INTEGER NOT NULL DEFAULT 0;
ALTER TABLE doc_chunks ADD COLUMN line_start INTEGER;
ALTER TABLE doc_chunks ADD COLUMN line_end INTEGER;
ALTER TABLE doc_chunks ADD COLUMN time_start_ms INTEGER;
ALTER TABLE doc_chunks ADD COLUMN time_end_ms INTEGER;
ALTER TABLE doc_chunks ADD COLUMN block_kind TEXT NOT NULL DEFAULT 'paragraph';
ALTER TABLE doc_chunks ADD COLUMN context TEXT;
CREATE INDEX doc_chunks_document ON doc_chunks(document_id,version,ordinal);
CREATE TABLE chunk_retrievals(run_id TEXT NOT NULL,chunk_id TEXT NOT NULL,scope_id TEXT NOT NULL,retrieved_at INTEGER NOT NULL,PRIMARY KEY(run_id,chunk_id));
CREATE INDEX source_events_run ON source_events(run_id);
CREATE TABLE memory_watermarks(principal_id TEXT NOT NULL,scope_id TEXT NOT NULL,last_rowid INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(principal_id,scope_id));
CREATE TABLE memory_activity(principal_id TEXT NOT NULL,at INTEGER NOT NULL,kind TEXT NOT NULL);
CREATE INDEX memory_activity_principal ON memory_activity(principal_id,at);
CREATE TABLE consolidation_schedules(principal_id TEXT PRIMARY KEY NOT NULL,timezone TEXT NOT NULL,mode TEXT NOT NULL,window_start_hour INTEGER NOT NULL,window_hours INTEGER NOT NULL,computed_at INTEGER NOT NULL);
CREATE TABLE consolidation_runs(id TEXT PRIMARY KEY NOT NULL,principal_id TEXT NOT NULL,state TEXT NOT NULL,started_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,finished_at INTEGER,checkpoint TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(checkpoint)),tokens_used INTEGER NOT NULL DEFAULT 0,report TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(report)));
CREATE TABLE consolidation_prompts(id INTEGER PRIMARY KEY,run_id TEXT NOT NULL,scope_id TEXT NOT NULL,step TEXT NOT NULL,scopes TEXT NOT NULL CHECK(json_valid(scopes)),prompt_hash TEXT NOT NULL,at INTEGER NOT NULL);
